const REPORT_SCHEMA = {"$schema":"http://json-schema.org/draft-07/schema#","$id":"optiflow/daily_report_summary","title":"Daily report narrative","type":"object","required":["headline","observations"],"additionalProperties":false,"properties":{"headline":{"type":"string","minLength":10,"maxLength":300},"observations":{"type":"array","maxItems":12,"items":{"type":"string","maxLength":400}},"segments_too_small_to_read":{"type":"array","maxItems":20,"items":{"type":"string","maxLength":200}},"questions_seen":{"type":"array","maxItems":12,"items":{"type":"object","required":["theme"],"additionalProperties":false,"properties":{"theme":{"type":"string","maxLength":200},"count":{"type":"number","minimum":0}}}},"objections_seen":{"type":"array","maxItems":12,"items":{"type":"object","required":["theme"],"additionalProperties":false,"properties":{"theme":{"type":"string","maxLength":200},"count":{"type":"number","minimum":0}}}},"attention":{"type":"array","maxItems":10,"items":{"type":"object","required":["issue"],"additionalProperties":false,"properties":{"issue":{"type":"string","maxLength":200},"detail":{"type":"string","maxLength":500},"suggested_action":{"type":"string","maxLength":300}}}},"notes_for_tomorrow":{"type":"array","maxItems":8,"items":{"type":"string","maxLength":300}}}};

const context = $('Prepare Report Input').first().json;
const text = ($input.first().json.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
const parsed = parseAiJson(text, REPORT_SCHEMA, { label: 'daily report' });

// The numbers stand on their own. If the narrative fails, the report still goes
// out with the measured figures.
const narrative = parsed.ok ? parsed.data : {
  headline: 'Narrative unavailable - figures below are unaffected.',
  observations: [],
  attention: [{ issue: 'report_narrative_failed', detail: (parsed.errors || []).slice(0, 3).join('; '), suggested_action: 'Check the model response in the execution log.' }]
};

return [{ json: { ...context, narrative } }];

